134	  /**
135	   * Optional TLS inputs, all resolved on the NXEON side (never read off the
136	   * customer's box). Omitting them simply drops the engine to a lower rung of
137	   * the certificate ladder, so existing callers keep working unchanged.
138	   */
139	  cloudflareToken?: string | null; // DNS-edit scoped token, for wildcard DNS-01
140	  acmeEmail?: string | null; // Let's Encrypt account contact
141	  knownDomains?: string[]; // the customer's registered Domain rows
142	  /**
143	   * Explicit consent to relocate Docker's stores onto an attached block-storage
144	   * volume. **Defaults to false** — the engine never takes a volume on its own,
145	   * because volumes are portable and mounting a system path on one makes the
146	   * volume undetachable. Falls back to `items.useVolumeForDocker` so the choice
147	   * can ride through Migration.items without a schema change.
148	   */
149	  useVolumeForDocker?: boolean;
150	};
