152	// ---- Timeouts -------------------------------------------------------------
153	const CONNECT_TIMEOUT_MS = 20_000;
154	const SETUP_TIMEOUT_MS = 60_000; // small writes, checks
155	const INSTALL_TIMEOUT_MS = 10 * 60_000; // package installs (apt/dnf can be slow)
156	const TRANSFER_TIMEOUT_MS = Number(process.env.MIGRATE_EXEC_TIMEOUT_MS ?? 45 * 60_000); // rsync/dump/import
157	const PROBE_TIMEOUT_MS = 3 * 60_000; // the read-only source inventory sweep
158	const IMAGE_TIMEOUT_MS = 30 * 60_000; // docker pull / save|load of one image
159	const GiB = 1024 ** 3;
160	const MiB = 1024 ** 2;
161	
162	// ---- Storage arithmetic ---------------------------------------------------
163	// A real migration filled a 25 GB root disk to 92% and two of three compose
164	// projects died with `no space left on device`, because the pre-flight only
165	// counted the ~11 GB file copy. Docker needs FAR more than the image bytes:
166	// `docker load`/`docker pull` writes the compressed stream, the content store
167	// (/var/lib/containerd/io.containerd.content.v1.content) keeps the layer blobs
168	// AND the snapshotter unpacks them again, and any `build` adds a build cache on
169	// top (measured: `docker builder prune -af` reclaimed 7.1 GB right after two
170	// image builds). So the allowance is 2× the source's image bytes plus a fixed
171	// floor, and free space is re-checked immediately before the image phase and
172	// again before every single image — never just once at the start.
173	const IMAGE_OVERHEAD_FACTOR = 2;
174	const FS_HEADROOM = 2 * GiB; // OS + apt + logs + dump files
175	const IMAGE_PHASE_FLOOR = 1.5 * GiB; // refuse to start an image op below this
176	const MAX_IMAGE_TRANSFER_BYTES = 24 * GiB; // total docker save/load budget
177	const MAX_SINGLE_IMAGE_BYTES = 12 * GiB;
178	// Where an attached-but-unused block device gets mounted, and the two Docker
179	// stores that are relocated onto it. `/var/lib/containerd` is a SEPARATE store
180	// from `/var/lib/docker` — with the containerd image store that get.docker.com
181	// installs on Ubuntu 22.04, layers and build ingest live under containerd, so
182	// relocating only /var/lib/docker leaves the root disk filling up anyway (it hit
183	// 100% in the field with 9.4 GB sitting in /var/lib/containerd).
184	const EXTRA_DISK_MOUNT = "/mnt/nxeon-data";
185	const DOCKER_STORES = ["/var/lib/docker", "/var/lib/containerd"] as const;
186	const MIN_EXTRA_DISK_BYTES = 4 * GiB;
187	/**
188	 * Block-storage volumes are PORTABLE: the Volumes UI promises they can be
189	 * attached to any of the customer's running servers, and that is what every
190	 * major provider does (EBS, DigitalOcean, Hetzner, Linode, Vultr). Relocating
191	 * `/var/lib/docker` + `/var/lib/containerd` onto a volume silently converts a
192	 * detachable add-on into one the server cannot boot without — so the engine
193	 * NEVER does it on its own. It happens only with explicit consent
194	 * (`useVolumeForDocker`), and when it does, this is said plainly in the run log
195	 * AND in the final summary.
196	 *
197	 * Deliberately NOT implemented: LVM pooling of several volumes into one
198	 * filesystem. It would give a customer the combined capacity, but it welds the
199	 * disks together permanently and destroys portability for ALL of them at once.
200	 */

