467	  | "certbot" | "certbot_dns_cloudflare";
468	
469	// Command that succeeds iff the package's main binary is already present.
470	const PKG_CHECK: Record<PkgKey, string> = {
471	  docker: "command -v docker >/dev/null 2>&1",
472	  mysql: "command -v mysql >/dev/null 2>&1 || command -v mariadb >/dev/null 2>&1",
