522	/**
523	 * Idempotently ensure each allowlisted package is present on the target. Runs
524	 * `apt-get update` once, then for each key: skip if the check passes, else try
525	 * apt → dnf → yum with the FIXED package string. Returns which were newly
526	 * installed / already present / failed. Never throws (best-effort per package).
527	 */
528	async function ensurePackages(
529	  conn: Client,
530	  keys: PkgKey[]
531	): Promise<{ key: PkgKey; ok: boolean; already: boolean; err?: string }[]> {
532	  const out: { key: PkgKey; ok: boolean; already: boolean; err?: string }[] = [];
533	  if (keys.length === 0) return out;
534	  // `DEBIAN_FRONTEND=noninteractive` is NOT sufficient on Ubuntu 22.04+.
535	  // `needrestart` hooks dpkg's post-install phase and opens an interactive
536	  // "which services should be restarted?" prompt on a tty nobody is reading,
537	  // which wedges apt until INSTALL_TIMEOUT_MS expires.
538	  //
539	  // Seen live on a real migration (2026-07-25): installing certbot blocked on
540	  // /usr/lib/needrestart/dpkg-status for the FULL 10-minute timeout, which was
541	  // the entire HTTPS window — the run finished with soulpilates.com.vn and
542	  // srv1182755.hstgr.cloud still on plain HTTP. A hang here does not just cost
543	  // time, it silently costs certificates.
544	  //
545	  // NEEDRESTART_MODE=a answers that prompt automatically (restart what's needed);
546	  // NEEDRESTART_SUSPEND=1 disables the hook outright on versions that honour it.
547	  // The force-conf* options settle the OTHER classic apt prompt — "a config file
548	  // you modified has changed" — by keeping the existing file, which is the right
549	  // answer on a machine we are migrating INTO.
550	  const APT_ENV = "DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=a NEEDRESTART_SUSPEND=1";
551	  const APT_OPTS = `-o Dpkg::Options::="--force-confdef" -o Dpkg::Options::="--force-confold"`;
552	  // Refresh apt metadata once (best-effort; ignored on non-apt systems). Also
553	  // finish any dpkg run a previous interrupted install left half-configured —
554	  // otherwise every later apt call inherits the wedge.
555	  await execRemote(conn, `${APT_ENV} dpkg --configure -a >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => {});
556	  await execRemote(conn, `${APT_ENV} apt-get update -y >/dev/null 2>&1 || true`, INSTALL_TIMEOUT_MS).catch(() => {});
557	  for (const key of keys) {
558	    const already = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((r) => r.code === 0).catch(() => false);
559	    if (already) {
560	      out.push({ key, ok: true, already: true });
561	      continue;
562	    }
563	    // Docker is special-cased: install via the OFFICIAL convenience script — the
564	    // SAME method the platform's own provisioning uses (buildCloudInit in
565	    // worker/index.ts). The apt/dnf package list fails on Ubuntu because
566	    // `docker-compose-plugin` isn't in Ubuntu's default apt repo, so the whole
567	    // install returned non-zero and Docker never came up. get.docker.com adds
568	    // Docker's own repo and installs docker-ce + the compose plugin across
569	    // Debian/Ubuntu/RHEL. The command is a FIXED constant (no source input);
570	    // still best-effort + logged like every other package.
571	    const install =
572	      key === "docker"
573	        ? `curl -fsSL https://get.docker.com | sh && systemctl enable --now docker`
574	        : `${APT_ENV} apt-get install -y ${APT_OPTS} ${PKG_APT[key]} ` +
575	          `|| dnf install -y ${PKG_DNF[key]} ` +
576	          `|| yum install -y ${PKG_DNF[key]}`;
577	    const r = await execRemote(conn, install, INSTALL_TIMEOUT_MS).catch((e) => ({ code: 1, stdout: "", stderr: String(e) }));
578	    const nowPresent = await execRemote(conn, PKG_CHECK[key], SETUP_TIMEOUT_MS).then((x) => x.code === 0).catch(() => false);
579	    if (nowPresent) {
580	      out.push({ key, ok: true, already: false });
581	    } else {
582	      const tail = (r.stderr || r.stdout || "").split("\n").filter(Boolean).slice(-2).join(" ").slice(0, 200);
583	      out.push({ key, ok: false, already: false, err: tail || `install exit ${r.code}` });
584	    }
585	  }
586	  return out;
587	}
