589	// ---- Plan derivation (prefer explicit items, re-validate everything) ------
590	function derivePlan(items: Items) {
591	  const scan = items.scan ?? {};
592	
593	  // Engines to dump: explicit dbEngines, else engines the scan marked present.
594	  const engineSet = new Set<string>();
595	  for (const e of items.dbEngines ?? []) engineSet.add(e);
596	  if (engineSet.size === 0) for (const e of scan.engines ?? []) if (e?.present && e.engine) engineSet.add(e.engine);
597	  const dbEngines = [...engineSet].filter((e): e is "mysql" | "postgres" => e === "mysql" || e === "postgres");
598	
599	  // Which MySQL-family engine to install on the target, from the DETECTED variant:
600	  // Oracle MySQL → mysql-server (clean same-engine); MariaDB (or undeterminable) →
601	  // mariadb-server (the existing safe default). This is a validated enum, never a
602	  // source string; it only selects a fixed package-allowlist KEY.
603	  const mysqlDetail = (scan.dbEngines ?? []).find((d) => d?.engine === "mysql");
604	  const mysqlVariant: "mysql" | "mariadb" = mysqlDetail?.variant === "mysql" ? "mysql" : "mariadb";
605	  const mysqlVersion: string | null = mysqlDetail?.version ?? null;
606	  const pgDetail = (scan.dbEngines ?? []).find((d) => d?.engine === "postgres");
607	  const pgVersion: string | null = pgDetail?.version ?? null;
608	
609	  const dockerVolumes = [...new Set(items.dockerVolumes ?? [])].filter((v) => VOLNAME_RE.test(v)).slice(0, 60);
610	  const composeDirs = [...new Set(items.composeDirs ?? [])].filter((p) => validPath(p)).slice(0, 40);
611	  const verifyPorts = [...new Set((items.verifyPorts ?? []).filter((p) => Number.isInteger(p) && p >= 1 && p <= 65535 && p !== 22))].slice(0, 60);
612	  const hasContainers = !!items.hasContainers || (scan.containers?.length ?? 0) > 0 || composeDirs.length > 0 || dockerVolumes.length > 0;
613	  const webServers = [...new Set(items.webServers ?? [])].filter((w): w is "nginx" | "apache" => w === "nginx" || w === "apache");
614	  const runtimes = [...new Set(items.runtimes ?? [])].filter((r): r is "nodejs" | "python3" => r === "nodejs" || r === "python3");
615	  const services = [...new Set((scan.services ?? []).map((s) => s?.name ?? "").filter((n) => SVCNAME_RE.test(n)))].slice(0, 30);
616	  const containers = (scan.containers ?? [])
617	    .map((c) => ({
618	      name: String(c?.name ?? ""),
619	      image: String(c?.image ?? ""),
620	      ports: String(c?.ports ?? ""),
621	      mounts: Array.isArray(c?.mounts) ? c!.mounts!.map((m) => String(m)) : [],
622	    }))
623	    .slice(0, 30);
624	
625	  const prereqs: PkgKey[] = [];
626	  // Install the engine variant that MATCHES the source (Oracle MySQL vs MariaDB).
627	  if (dbEngines.includes("mysql")) prereqs.push(mysqlVariant === "mysql" ? "mysql_oracle" : "mysql");
628	  if (dbEngines.includes("postgres")) prereqs.push("postgresql");
629	  if (hasContainers) prereqs.push("docker");
630	  for (const w of webServers) prereqs.push(w === "nginx" ? "nginx" : "apache");
