725	function human(n: number): string {
726	  if (!Number.isFinite(n) || n <= 0) return "0 B";
727	  const u = ["B", "KB", "MB", "GB", "TB"];
728	  let i = 0;
729	  let v = n;
730	  while (v >= 1024 && i < u.length - 1) {
731	    v /= 1024;
732	    i++;
733	  }
734	  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${u[i]}`;
