869	    const line = raw.replace(/\r$/, "");
870	    if (!line) continue;
871	    const parts = line.split("\t");
872	    const kind = parts[0];
873	
874	    if (kind === "INVENTORY_OK") {
875	      inv.probed = true;
876	    } else if (kind === "HASDOCKER") {
877	      inv.hasDocker = true;
878	    } else if (kind === "IMAGE" && parts.length >= 2) {
