880	      const ref = clean(seg[0], 255);
881	      if (!validImageRef(ref) || inv.images.some((i) => i.ref === ref)) continue;
882	      if (inv.images.length >= 120) continue;
883	      inv.images.push({ ref, sizeBytes: parseDockerSize(seg[1] ?? ""), local: isLocalImageRef(ref) });
884	    } else if (kind === "DVOLBYTES" && parts.length >= 2) {
885	      const n = Number(parts[1]);
886	      if (Number.isFinite(n) && n > 0) inv.volumeBytes = n;
887	    } else if (kind === "C" && parts.length >= 3) {
888	      const cid = clean(parts[1], 64);
889	      if (!/^[0-9a-f]{6,64}$/i.test(cid)) continue;
890	      let c = byId.get(cid);
891	      if (!c) {
892	        if (byId.size >= 40) continue;
893	        c = {
