899	      }
900	      const body = parts.slice(2).join("\t");
901	      const sp = body.indexOf(" ");
902	      const key = sp < 0 ? body : body.slice(0, sp);
903	      const val = sp < 0 ? "" : body.slice(sp + 1);
904	      switch (key) {
905	        case "name": c.name = clean(val, 128).replace(/^\//, ""); break;
906	        case "image": c.image = clean(val, 255); break;
907	        case "state": c.state = clean(val, 32); break;
908	        case "restart": c.restart = clean(val, 32); break;
909	        case "netmode": c.netmode = clean(val, 128); break;
910	        case "runuser": c.runuser = clean(val, 64); break;
911	        case "workdir": c.workdir = clean(val, 255); break;
912	        case "privileged": c.privileged = clean(val, 8) === "true"; break;
913	        case "devices": c.devices = Math.max(0, Number(clean(val, 8)) || 0); break;
914	        case "caps": c.caps = clean(val, 512).split(/\s+/).filter(Boolean).slice(0, 20); break;
915	        case "cmd": c.cmd = clean(val, 1024); break;
916	        case "entrypoint": c.entrypoint = clean(val, 1024); break;
917	        case "imagecmd": c.imagecmd = clean(val, 1024); break;
918	        case "imageentrypoint": c.imageentrypoint = clean(val, 1024); break;
919	        case "project": c.project = clean(val, 128); break;
920	        case "port": {
921	          // "<containerPort>/<proto> <hostIp|-> <hostPort>"
922	          const t = clean(val, 128).split(/\s+/);
923	          if (t.length < 3 || c.ports.length >= 20) break;
924	          const pm = /^(\d{1,5})\/(tcp|udp)$/.exec(t[0]);
925	          const hp = Number(t[2]);
926	          if (!pm || !Number.isInteger(hp) || hp < 1 || hp > 65535) break;
927	          const cp = Number(pm[1]);
928	          if (!Number.isInteger(cp) || cp < 1 || cp > 65535) break;
