936	          const t = clean(val, 1024).split(/\s+/);
937	          if (t.length < 5 || c.mounts.length >= 20) break;
938	          c.mounts.push({
939	            kind: t[0],
940	            name: t[1] === "-" ? "" : t[1],
941	            source: t[2] === "-" ? "" : t[2],
942	            dest: t[3],
943	            rw: t[4] === "true",
944	          });
945	          break;
946	        }
947	        case "net": {
