968	        const d = normalizeDomain(t);
969	        if (d && !inv.domains.includes(d)) inv.domains.push(d);
970	      }
971	    } else if (kind === "LEDIR") {
972	      inv.hasLetsEncrypt = true;
973	    } else if (kind === "TLSCERT" && parts.length >= 2) {
974	      const d = normalizeDomain(parts[1]);
975	      if (d && inv.tlsCerts.length < 60 && !inv.tlsCerts.includes(d)) inv.tlsCerts.push(d);
976	    } else if (kind === "CRONUSER" && parts.length >= 3) {
977	      const n = clean(parts[1], 64);
978	      const dir = clean(parts[2], 128);
979	      if (!USER_RE.test(n) || !validPath(dir) || inv.cronUsers.length >= 40) continue;
980	      if (inv.cronUsers.some((c) => c.name === n)) continue;
981	      inv.cronUsers.push({ name: n, dir });
982	    } else if (kind === "CROND") {
983	      inv.hasCronD = true;
984	    } else if (kind === "PWUSER" && parts.length >= 6) {
985	      const name = clean(parts[1], 64);
986	      const uid = Number(parts[2]);
987	      const gid = Number(parts[3]);
988	      const home = clean(parts[4], 255);
989	      const shell = clean(parts[5], 255);
990	      if (inv.users.length >= 40) continue;
991	      if (!USER_RE.test(name)) continue;
992	      if (!Number.isInteger(uid) || uid < 1000 || uid >= 65534) continue;
993	      if (!Number.isInteger(gid) || gid < 0 || gid >= 65534) continue;
994	      if (!validPath(home)) continue;
995	      inv.users.push({ name, uid, gid, home, shell: LOGIN_SHELLS.has(shell) ? shell : NOLOGIN });
996	    } else if (kind === "NGXT" && parts.length >= 2) {
997	      if (inv.nginxDump.length < 4000) inv.nginxDump.push(clean(parts.slice(1).join("\t"), 1000));
998	    } else if (kind === "APCT" && parts.length >= 2) {
999	      if (inv.apacheDump.length < 800) inv.apacheDump.push(clean(parts.slice(1).join("\t"), 1000));
1000	    } else if (kind === "SRCIP" && parts.length >= 2) {
1001	      const ip = clean(parts[1], 64);
1002	      if ((IPV4_RE.test(ip) || IPV6_RE.test(ip)) && !inv.srcIps.includes(ip) && inv.srcIps.length < 12) inv.srcIps.push(ip);
1003	    } else if (kind === "SRCHOST" && parts.length >= 2) {
1004	      const h = clean(parts[1], 253).toLowerCase();
1005	      // Only real, shell-inert names. `localhost` is on every box and is never stale.
1006	      if (HOSTNAME_RE.test(h) && h !== "localhost" && !inv.srcHostnames.includes(h) && inv.srcHostnames.length < 6) {
1007	        inv.srcHostnames.push(h);
1008	      }
1009	    } else if (kind === "PWGROUP" && parts.length >= 3) {
1010	      const name = clean(parts[1], 64);
1011	      const gid = Number(parts[2]);
1012	      if (inv.groups.length >= 40 || !USER_RE.test(name)) continue;
1013	      if (!Number.isInteger(gid) || gid < 1000 || gid >= 65534) continue;
1014	      inv.groups.push({ name, gid });
1015	    }
1016	  }
1017	
1018	  inv.containers = [...byId.values()].filter((c) => CONTNAME_RE.test(c.name) && validImageRef(c.image));
1019	  inv.imageBytes = inv.images.reduce((n, i) => n + i.sizeBytes, 0);
1020	  return inv;
1021	}
