// ---- Heartbeats for the long steps ----------------------------------------
/**
 * A single remote command can legitimately run for MINUTES — `apt-get install`,
 * `docker save | ssh | docker load`, `certbot certonly`. During that time the
 * engine emits nothing, so the customer's progress bar freezes and the run looks
 * hung.
 *
 * Seen live on 2026-07-25: the run sat silent on 89% "Securing your site…" for a
 * full TEN MINUTES while a certbot install blocked on needrestart. The customer
 * had no way to tell a wedged migration from a slow one.
 *
 * So the long steps run inside this wrapper, which emits ONE cheap line every
 * `everyMs` naming what is still running and for how long. It is deliberately
 * dumb: no extra SSH traffic, no state on the target, and a failing `say` can
 * never affect the work it is narrating.
 */
const HEARTBEAT_MS = 45_000;

async function withHeartbeat<T>(
  what: string,
  say: (line: string) => Promise<void>,
  run: () => Promise<T>,
  everyMs: number = HEARTBEAT_MS
): Promise<T> {
  const started = Date.now();
  let saying = false;
  const timer = setInterval(() => {
    // Never let two heartbeats overlap, and never let a reporting failure
    // surface as an unhandled rejection — this is narration, not work.
    if (saying) return;
    saying = true;
    const secs = Math.round((Date.now() - started) / 1000);
    const elapsed = secs >= 120 ? `${Math.round(secs / 60)} min` : `${secs}s`;
    Promise.resolve(say(`  Still working: ${what} (${elapsed} so far) — this step can take a while.`))
      .catch(() => {})
      .finally(() => {
        saying = false;
      });
  }, Math.max(15_000, everyMs));
  // `unref` keeps a stray interval from holding the worker process open.
  (timer as unknown as { unref?: () => void }).unref?.();
  try {
    return await run();
  } finally {
    clearInterval(timer);
  }
}

