async function httpProbe(
  conn: Client,
  url: string,
  resolve?: { domain: string; port: number }
): Promise<{ code: string; body: string }> {
  const res = resolve ? `--resolve ${resolve.domain}:${resolve.port}:127.0.0.1 ` : "";
  // The BODY is fetched as well as the status, because a status code alone
  // cannot tell a real site from the stock Apache/nginx default page — see
  // defaultPageReason. It lands in a `mktemp` file rather than a fixed /tmp
  // name: on a migrated multi-user box a predictable path under /tmp is a
  // symlink-overwrite waiting to happen, and this engine never takes a
  // destructive risk with the customer's files.
  const r = await sh(
    conn,
    `f=$(mktemp 2>/dev/null || echo /dev/null); ` +
      `c=$(curl -sS -k --max-time 12 ${res}-o "$f" -w '%{http_code}' ${url} 2>/dev/null); ` +
      `[ -n "$c" ] || c=000; printf 'NXCODE:%s\\n' "$c"; head -c 4096 "$f" 2>/dev/null; ` +
      `[ "$f" = /dev/null ] || rm -f "$f"`,
    SETUP_TIMEOUT_MS
  );
  const out = String(r.stdout ?? "");
  const m = /NXCODE:(\d{3})/.exec(out);
  const nl = out.indexOf("\n");
  return { code: m ? m[1] : "000", body: probeBody(nl < 0 ? "" : out.slice(nl + 1)) };
}

/** Status-code-only probe (unchanged contract) — now sharing one code path. */
async function httpCode(conn: Client, url: string, resolve?: { domain: string; port: number }): Promise<string> {
  return (await httpProbe(conn, url, resolve)).code;
}

/**
 * Bound a response body for pattern-matching. Deliberately NOT `clean()`:
 * `clean` strips ALL control characters including newlines, which would glue
 * "Apache2 Debian Default\nPage" into "Apache2 Debian DefaultPage" and make the
 * default-page markers unmatchable. Newline/tab/CR survive; everything else
 * becomes a space.
 */
function probeBody(raw: string, max = 4096): string {
  // eslint-disable-next-line no-control-regex
  return String(raw ?? "").replace(/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/g, " ").slice(0, max);
}

/**
 * A response body shorter than this (after trimming) is not a website. A real
 * page — even a JavaScript app whose HTML is just a mount point — is hundreds of
 * bytes; a truly empty 200 is what a misrouted vhost or an empty document root
 * returns. Deliberately measured on the RAW body, not on stripped-tag "visible
 * text": a React/Next shell has almost no visible text and must NOT be flagged.
 */
const NEAR_EMPTY_BODY_BYTES = 64;

/**
 * The stock pages a freshly-installed web server serves when NOTHING has claimed
 * the request. Every one of these answers 200, which is why the old
 * "make a real request to each domain" check passed for a dead site.
 *
 * Real incident, 2026-07-25: the run reported the customer's main site as
 * serving. The browser showed a certificate warning and then the Apache2 Debian
 * Default Page — apache2 had been re-enabled from the source and was answering
 * on a port our generated nginx config was supposed to own. A 200 from the
 * distribution's placeholder is a FAILED migration, not a successful one.
 */
const DEFAULT_PAGE_MARKERS: { re: RegExp; what: string }[] = [
  { re: /Apache2\s+Debian\s+Default\s+Page/i, what: "the Apache2 Debian default page" },
  { re: /Apache2\s+Ubuntu\s+Default\s+Page/i, what: "the Apache2 Ubuntu default page" },
  { re: /Apache\s+HTTP\s+Server\s+Test\s+Page/i, what: "the stock Apache test page" },
  // The classic /var/www/html/index.html: `<html><body><h1>It works!</h1></body></html>`.
  // Anchored on the heading so a real site that merely contains the words
  // "it works!" in its copy is never mistaken for a placeholder.
  { re: /<h1>\s*It\s+works!\s*<\/h1>/i, what: `Apache's stock "It works!" page` },
  { re: /Welcome\s+to\s+nginx!/i, what: `nginx's stock "Welcome to nginx!" page` },
];

/**
 * Why this response is a placeholder rather than the customer's site, or "" when
 * it looks like real content. Content is only judged on a 2xx: a 301 to HTTPS or
 * a 401/404 legitimately has a tiny (or empty) body and the status alone already
 * proves the vhost matched.
 */
function defaultPageReason(code: string, body: string): string {
  if (!/^2\d\d$/.test(code)) return "";
  for (const m of DEFAULT_PAGE_MARKERS) {
    if (m.re.test(body)) return `it answered ${code} with ${m.what}, not your site`;
  }
  if (body.trim().length < NEAR_EMPTY_BODY_BYTES) {
    return `it answered ${code} with an empty page (${body.trim().length} bytes) — the document root has no content`;
  }
  return "";
}

/**
 * The hostnames on the certificate this server actually presents for `domain`,
 * read with SNI so it is the same certificate a browser would be shown.
 * `null` means we could not determine it (no openssl, or nothing on 443) — an
 * unknown is never treated as a failure.
 *
 * Real incident, 2026-07-25: studionexis.com was served nexis.revsports.ca's
 * certificate, so every visitor got ERR_CERT_COMMON_NAME_INVALID before they
 * ever reached the site — and the run reported that domain as serving, because
 * the probe used `-k` and only looked at the status code.
 */
async function servedCertNames(conn: Client, domain: string): Promise<string[] | null> {
  if (!DOMAIN_RE.test(domain)) return null;
  const r = await sh(
    conn,
    `T=$(command -v timeout >/dev/null 2>&1 && echo 'timeout 8'); ` +
      `command -v openssl >/dev/null 2>&1 || exit 3; ` +
      `$T openssl s_client -connect 127.0.0.1:443 -servername ${domain} </dev/null 2>/dev/null ` +
      `| openssl x509 -noout -subject -ext subjectAltName 2>/dev/null`,
    SETUP_TIMEOUT_MS
  );
  const out = probeBody(r.stdout, 4096);
  if (!out.trim()) return null;
  const names: string[] = [];
  // `subject=CN = example.com`, `subject= /C=US/CN=example.com`, `CN=example.com`.
  const cn = /CN\s*=\s*([^,/\r\n]+)/.exec(out);
  if (cn) names.push(cn[1].trim());
  for (const m of out.matchAll(/DNS:\s*([^,\s]+)/g)) names.push(m[1].trim());
  const uniq = [...new Set(names.map((n) => n.toLowerCase().replace(/\.$/, "")).filter(Boolean))].slice(0, 40);
  return uniq.length ? uniq : null;
}

/** Does a certificate carrying `certNames` cover `domain`? (`*.x` = ONE label.) */
function certCoversName(certNames: string[], domain: string): boolean {
  const d = domain.toLowerCase().replace(/\.$/, "");
  for (const n of certNames) {
    if (n === d) return true;
    if (n.startsWith("*.")) {
      const base = n.slice(2);
      const dot = d.indexOf(".");
      if (base && dot > 0 && d.slice(dot + 1) === base) return true;
    }
  }
  return false;
}

/**
 * "Serving" means the web stack answered with an HTTP status — 200/301/401/404
 * all prove the port is bound, the vhost matched and something is behind it.
 * Only a connection failure (000) or a 5xx counts as not serving.
 *
 * This is necessary but NOT sufficient — see defaultPageReason and
 * servedCertNames for the two ways a 200 still means a dead site.
 */
function isServing(code: string): boolean {
  return /^[1-4]\d\d$/.test(code);
}

// ===========================================================================
// MIGRATED SYSTEMD UNITS — EXEC PRE-FLIGHT + HEALTH GATE
// ===========================================================================
/**
 * A unit file is the one thing in a migration that is copied VERBATIM and then
 * executed. Everything inside it — interpreter path, working directory, build
 * artefacts — is a statement about the OLD machine, and none of it is checked
 * before `systemctl enable --now` runs.
 *
 * Real incident, 2026-07-25 (and this had happened BEFORE — it is field note #13,
 * documented after a previous migration and it recurred anyway, which is exactly
 * why it is now an executable pre-flight instead of a paragraph in a document):
 *
 *     nexis-next.service
 *       ExecStart=/usr/local/bin/node /opt/nexis/node_modules/next/dist/bin/next start -p 3105
 *
 * The source had a hand-installed Node at /usr/local/bin/node. The target has
 * apt's Node 20 at /usr/bin/node and NOTHING at /usr/local/bin/node, so systemd
 * failed the exec with status 203/EXEC. The unit crash-looped 78 times and the
 * migration reported SUCCESS.
 *
 * So: before enabling anything, resolve the absolute executable of every
 * ExecStart / ExecStartPre / ExecStartPost. Missing ⇒ symlink to the same binary
 * found elsewhere on the target, else copy it from the source, else BLOCK and say
 * exactly which unit wants exactly which path.
 */
type UnitExecRef = { directive: string; path: string };

/**
 * Fold systemd's line continuations. A unit may legally spread one ExecStart over
 * several lines with a trailing backslash, and reading it line-at-a-time would
 * see a directive whose command is empty and skip the check entirely.
 */
function unfoldUnitLines(text: string): string[] {
  const out: string[] = [];
  let acc = "";
  for (const raw of String(text ?? "").split("\n")) {
    const line = raw.replace(/\r$/, "");
    if (/\\\s*$/.test(line)) {
      acc += line.replace(/\\\s*$/, " ");
      continue;
    }
    out.push((acc + line).trim());
    acc = "";
  }
  if (acc.trim()) out.push(acc.trim());
  return out;
}

/**
 * Every ABSOLUTE executable path a unit's Exec* directives will try to run.
 *
 * Defensive by design, because a unit file is untrusted input from another
 * machine:
 *   - `ExecStart=-/path`  the `-` (ignore failure), `@` (argv[0] override),
 *     `+` (full privileges), `!` / `!!` (no-setuid variants) prefixes may appear
 *     in any order and combination and are stripped before the path is read;
 *   - quoted paths (`ExecStart="/opt/my app/bin/run" --flag`) are unquoted;
 *   - an EMPTY assignment (`ExecStart=`) is systemd's list-reset and is skipped;
 *   - a bare command (`ExecStart=node server.js`) is resolved from PATH by
 *     systemd itself, so it is deliberately IGNORED — we cannot check it and
 *     guessing would be worse than silence;
 *   - a path carrying a `%` specifier (`/usr/bin/%i`) can only be resolved by
 *     systemd, so it is skipped rather than mis-reported. It also would not pass
 *     PATH_RE, which is what keeps every value here shell-inert.
 */
function parseUnitExecPaths(text: string): UnitExecRef[] {
  const out: UnitExecRef[] = [];
  const seen = new Set<string>();
  for (const line of unfoldUnitLines(text)) {
    const m = /^(ExecStart|ExecStartPre|ExecStartPost)\s*=\s*(.*)$/.exec(line);
    if (!m) continue;
    let rhs = m[2].trim();
    if (!rhs) continue; // `ExecStart=` — a list reset, not a command
    rhs = rhs.replace(/^[-@+!]+\s*/, "").trim();
    if (!rhs) continue;
    let exe: string;
    const q = rhs[0];
    if (q === '"' || q === "'") {
      const end = rhs.indexOf(q, 1);
      exe = end > 0 ? rhs.slice(1, end) : rhs.slice(1);
    } else {
      exe = rhs.split(/\s+/)[0] ?? "";
    }
    exe = exe.trim();
    if (!exe.startsWith("/")) continue; // PATH-resolved — not ours to check
    if (!validPath(exe)) continue; // %-specifiers and odd charsets: unresolvable here
    const key = `${m[1]}|${exe}`;
    if (seen.has(key) || out.length >= 12) continue;
    seen.add(key);
    out.push({ directive: m[1], path: exe });
  }
  return out;
}

/**
 * Resolve every missing Exec* binary for one unit BEFORE it is enabled.
 * Returns the human-readable repairs made and a blocking entry for anything we
 * refused to guess at. Never throws; never removes or overwrites anything —
 * every action here only ever CREATES a path that did not exist.
 */
async function preflightUnitExecs(opts: {
  conn: Client;
  unit: string;
  unitFile: string;
  existsOnSource: (path: string) => Promise<boolean>;
  copyFromSource: (path: string) => Promise<boolean>;
  say: (line: string) => Promise<void>;
}): Promise<{ ok: boolean; repairs: string[]; blockers: PendingItem[] }> {
  const { conn, unit, unitFile, existsOnSource, copyFromSource, say } = opts;
  const repairs: string[] = [];
  const blockers: PendingItem[] = [];
  if (!SVCNAME_RE.test(unit) || !validPath(unitFile)) return { ok: true, repairs, blockers };

  const body = await sh(conn, `cat ${unitFile} 2>/dev/null`, SETUP_TIMEOUT_MS);
  const refs = parseUnitExecPaths(body.stdout);
  for (const ref of refs) {
    if (await shOk(conn, `test -x ${ref.path}`)) continue;

    // It exists but is not executable — a real 203/EXEC cause too. Reported, not
    // silently chmod-ed: changing the mode of the customer's own file is their
    // call, and the command to do it is one line.
    if (await shOk(conn, `test -e ${ref.path}`)) {
      blockers.push({
        domain: `${unit}.service`,
        why: `its ${ref.directive} runs ${ref.path}, which exists on this server but is not executable — systemd will fail it with 203/EXEC`,
        fix: `chmod +x ${ref.path} && systemctl restart ${unit}`,
      });
      continue;
    }

    // 1. The SAME program under a different prefix. This is the common case:
    //    /usr/local/bin/node (hand-installed on the source) vs /usr/bin/node
    //    (apt, on the target). A symlink makes the copied unit correct without
    //    editing the customer's unit file.
    const base = ref.path.slice(ref.path.lastIndexOf("/") + 1);
    const dir = parentDir(ref.path);
    if (/^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/.test(base) && validPath(dir)) {
      const found = clean((await sh(conn, `command -v ${base} 2>/dev/null`)).stdout, 255);
      if (found && found !== ref.path && validPath(found) && (await shOk(conn, `test -x ${found}`))) {
        // `ln -s` (not -sfn): we already proved the path is absent, so a plain
        // symlink can never clobber anything. If a race created it meanwhile we
        // want the loud failure, not a silent replacement.
        const ok = await shOk(conn, `mkdir -p ${dir} && ln -s ${found} ${ref.path}`);
        if (ok && (await shOk(conn, `test -x ${ref.path}`))) {
          repairs.push(`${unit}: ${ref.directive} wanted ${ref.path}, which is not on this server — linked it to ${found}`);
          await say(`  ${unit}: ${ref.path} does not exist here, so it was linked to ${found} (the same program, installed in a different place).`);
          continue;
        }
      }
    }

    // 2. Not present under any name — bring the actual file across.
    if (await existsOnSource(ref.path)) {
      if (await copyFromSource(ref.path)) {
        repairs.push(`${unit}: copied ${ref.path} from the old server so ${ref.directive} can run`);
        await say(`  ${unit}: copied ${ref.path} across from the old server.`);
        continue;
      }
    }

    // 3. Refuse to guess. A unit that cannot exec is worth one loud line.
    blockers.push({
      domain: `${unit}.service`,
      why:
        `its ${ref.directive} runs ${ref.path}, which does not exist on this server and is not installed anywhere else here ` +
        `(systemd fails this as 203/EXEC and restarts the service forever)`,
      fix:
        `install the program that provides ${base} on this server, then either symlink it — ln -s "$(command -v ${base})" ${ref.path} — ` +
        `or edit ${unitFile} to the real path, and run: systemctl daemon-reload && systemctl restart ${unit}`,
    });
  }
  return { ok: blockers.length === 0, repairs, blockers };
}

/** Node-side wait. Used only to let systemd settle before we judge a unit. */
const delay = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));

type UnitState = { active: string; sub: string; restarts: number };

/** One `systemctl show` read of the fields that decide "is this unit healthy". */
async function unitState(conn: Client, unit: string): Promise<UnitState> {
  if (!SVCNAME_RE.test(unit)) return { active: "unknown", sub: "", restarts: 0 };
  const r = await sh(
    conn,
    `systemctl show ${unit}.service --property=ActiveState --property=SubState --property=NRestarts --no-pager 2>/dev/null`,
    SETUP_TIMEOUT_MS
  );
  const out = clean(r.stdout, 512);
  const pick = (k: string) => new RegExp(`${k}=([A-Za-z0-9-]*)`).exec(out)?.[1] ?? "";
  const n = Number(pick("NRestarts"));
  return { active: pick("ActiveState") || "unknown", sub: pick("SubState"), restarts: Number.isFinite(n) ? n : 0 };
}

/** The last few journal lines for a unit, bounded — the ACTUAL error text. */
async function unitJournal(conn: Client, unit: string, lines = 12): Promise<string> {
  if (!SVCNAME_RE.test(unit)) return "";
  const r = await sh(conn, `journalctl -u ${unit}.service -n ${lines} --no-pager -o cat 2>/dev/null`, SETUP_TIMEOUT_MS);
  return probeBody(r.stdout, 2000);
}

/**
 * The recognisable "this was never built" failure. `/opt/nexis` came across with
 * a `.next` directory that held a dev cache, not a production build, so even
 * with the Node path fixed the unit exits 1 in a loop forever. Naming the fix
 * (`next build`) is the difference between a customer fixing it in a minute and
 * opening a ticket.
 */
const NEXT_NO_BUILD_RE = /Could not find a production build in the ['"`]?\.?\/?\.next['"`]?\s*directory/i;

/**
 * AFTER enabling the migrated units, prove each one is actually up.
 *
 * `systemctl enable --now` returning 0 means "systemd accepted the job", not
 * "the program runs" — and `is-active` sampled immediately after can read
 * `activating` for a unit that is about to die, or even `active` in the window
 * between a restart and the next crash. So we settle, then sample the restart
 * counter TWICE: a unit whose NRestarts is climbing is crash-looping no matter
 * what its state says at any instant. A service that has restarted 78 times must
 * never be silent.
 */
async function unitHealthGate(opts: {
  conn: Client;
  units: string[];
  say: (line: string) => Promise<void>;
}): Promise<{ healthy: string[]; blockers: PendingItem[] }> {
  const { conn, units, say } = opts;
  const healthy: string[] = [];
  const blockers: PendingItem[] = [];
  const list = units.filter((u) => SVCNAME_RE.test(u)).slice(0, 30);
  if (!list.length) return { healthy, blockers };

  await say(`  Waiting for ${list.length} migrated service(s) to settle before judging them.`);
  await delay(12_000);
  const first = new Map<string, UnitState>();
  for (const u of list) first.set(u, await unitState(conn, u));
  // A crash-loop needs a second look: RestartSec is typically 100ms–5s, so a
  // 15-second window catches any unit that is cycling.
  await delay(15_000);

  for (const u of list) {
    const a = first.get(u) ?? { active: "unknown", sub: "", restarts: 0 };
    const b = await unitState(conn, u);
    const climbing = b.restarts > a.restarts;
    const ok = b.active === "active" && !climbing;
    if (ok) {
      healthy.push(u);
      continue;
    }

    const journal = await unitJournal(conn, u);
    const tail = journal.split("\n").filter((l) => l.trim()).slice(-4).join(" | ").slice(0, 400);
    const state = climbing
      ? `it is crash-looping — systemd has restarted it ${b.restarts} time(s) and the counter went up again while we watched`
      : b.active === "failed"
        ? `it is in the failed state (${b.sub || "failed"})`
        : `it never became active (systemd reports ${b.active}${b.sub ? `/${b.sub}` : ""})`;

    if (NEXT_NO_BUILD_RE.test(journal)) {
      blockers.push({
        domain: `${u}.service`,
        why:
          `${state}. The application was copied across but was never BUILT here — Next.js reports ` +
          `"Could not find a production build in the '.next' directory", so it exits immediately every time`,
        fix: `run the production build in the app's directory, then start it: npm ci --omit=dev && npx next build && systemctl restart ${u}`,
      });
      await say(`  ${u}: not running — the app has no production build on this server (\`next build\` has never been run here).`);
      continue;
    }

    blockers.push({
      domain: `${u}.service`,
      why: `${state}${tail ? `. Its last log lines were: ${tail}` : ""}`,
      fix: `systemctl status ${u} --no-pager -l; journalctl -u ${u} -n 50 --no-pager`,
    });
    await say(`  ${u}: NOT running — ${state}.`);
  }
  return { healthy, blockers };
}

/**
 * The other host web servers. When we generate our OWN configuration for one of
 * them, every other one is a latent hazard rather than a spare: they all want
 * port 80/443 and only one can have it.
 *
 * Real incident, 2026-07-25: `apache2` was re-enabled from the source's service
 * list while we generated an nginx config. It could not bind port 80, so it sat
 * `enabled + failed` — quiet today, but first to start after a reboot, where the
 * race decides whether the customer's site or the Apache2 Debian Default Page
 * answers. (The default page is exactly what the customer saw.)
 */
const HOST_WEB_SERVERS = ["nginx", "apache2", "httpd", "caddy", "lighttpd"] as const;

/**
 * Disable + mask every host web server we did NOT choose. Masking (not merely
 * disabling) because a package upgrade or a leftover dependency can re-enable a
 * disabled unit, and the whole point is that this cannot come back on its own at
 * the next reboot. Fully reversible, and the command to reverse it is logged.
 */
async function standDownOtherWebServers(
  conn: Client,
  chosen: "nginx" | "apache",
  say: (line: string) => Promise<void>
): Promise<string[]> {
  const keep = chosen === "apache" ? ["apache2", "httpd"] : ["nginx"];
  const stood: string[] = [];
  for (const svc of HOST_WEB_SERVERS) {
    if (keep.includes(svc)) continue;
    // Only touch units this machine actually has, so the log stays truthful.
    const known = await shOk(conn, `systemctl list-unit-files ${svc}.service --no-legend 2>/dev/null | grep -q ${svc}`);
    if (!known) continue;
    const wasEnabled = clean((await sh(conn, `systemctl is-enabled ${svc} 2>/dev/null`)).stdout, 32);
    const wasActive = clean((await sh(conn, `systemctl is-active ${svc} 2>/dev/null`)).stdout, 32);
    if (wasEnabled === "masked") continue;
    await sh(conn, `systemctl disable --now ${svc} >/dev/null 2>&1; systemctl mask ${svc} >/dev/null 2>&1; true`, SETUP_TIMEOUT_MS);
    if (clean((await sh(conn, `systemctl is-enabled ${svc} 2>/dev/null`)).stdout, 32) === "masked") {
      stood.push(svc);
      await say(
        `  Disabled ${svc} on this server (it was ${wasEnabled || "installed"}${wasActive === "active" ? ", running" : ""}) — ` +
          `${chosen === "apache" ? "Apache" : "nginx"} owns ports 80/443 here and two web servers cannot share them. To bring it back: systemctl unmask ${svc}.`
      );
    }
  }
  return stood;
}

