// ---- 11. systemd services (best-effort copy of the unit + enable) -----
if (plan.services.length) {
  await report(90, "Re-enabling services…", `Re-enabling up to ${plan.services.length} service(s) that ran on the source.`);
  for (const svc of plan.services) {
    const unit = `/etc/systemd/system/${svc}.service`;
    // Copy the unit file only if it exists on the source (best-effort).
    const r = await execRemote(conn, rsyncPull(unit, "/etc/systemd/system"), SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
    if (r.code !== 0) {
      push({ step: `Service ${svc}`, status: "copied", detail: "unit not a simple /etc/systemd/system file — re-enable manually" });
      continue;
    }
    await execRemote(conn, `systemctl daemon-reload 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
    const en = await execRemote(conn, `systemctl enable --now ${svc} 2>/dev/null`, SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
    const active = await execRemote(conn, `systemctl is-active ${svc} 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim() === "active").catch(() => false);
    if (en.code === 0 && active) push({ step: `Service ${svc}`, status: "running", detail: "unit copied, enabled and active" });
    else push({ step: `Service ${svc}`, status: "copied", detail: "unit copied but not confirmed active — check `systemctl status`" });
  }
}

input.new_string:
// ---- 11. systemd services (copy the unit → PRE-FLIGHT → enable → GATE) --
// Two things changed here after 2026-07-25, both because the old loop's only
// question was "did systemctl accept the job":
//   a) a unit whose ExecStart names a binary this machine does not have is
//      REPAIRED (or blocked) BEFORE it is enabled — see preflightUnitExecs;
//   b) `is-active` sampled the instant after `enable --now` is not evidence,
//      so every unit is judged again afterwards by unitHealthGate.
const enabledUnits: string[] = [];
if (plan.services.length) {
  await report(90, "Re-enabling services…", `Re-enabling up to ${plan.services.length} service(s) that ran on the source.`);
  // The source's own service list contains its web server. Re-enabling it
  // while we serve with a different one is what left apache2 `enabled +
  // failed` on the customer's box, one reboot away from answering with the
  // Apache2 Debian Default Page.
  const ourWebServer = webKind === "apache" ? ["apache2", "httpd"] : webKind === "nginx" ? ["nginx"] : [];
  for (const svc of plan.services) {
    if ((webKind === "nginx" || webKind === "apache") && (HOST_WEB_SERVERS as readonly string[]).includes(svc) && !ourWebServer.includes(svc)) {
      push({
        step: `Service ${svc}`,
        status: "skipped",
        detail: `deliberately NOT re-enabled — this server serves your sites with ${webKind === "apache" ? "Apache" : "nginx"}, and a second web server would fight it for ports 80/443 (and could win the race after a reboot)`,
      });
      await report(90, "Re-enabling services…", `  ${svc}: left disabled on purpose — ${webKind === "apache" ? "Apache" : "nginx"} owns ports 80/443 here.`);
      continue;
    }
    const unit = `/etc/systemd/system/${svc}.service`;
    // Copy the unit file only if it exists on the source (best-effort).
    const r = await execRemote(conn, rsyncPull(unit, "/etc/systemd/system"), SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
    if (r.code !== 0) {
      push({ step: `Service ${svc}`, status: "copied", detail: "unit not a simple /etc/systemd/system file — re-enable manually" });
      continue;
    }

    // PRE-FLIGHT: resolve the unit's absolute executables against THIS
    // machine before systemd is asked to run them.
    const pf = await preflightUnitExecs({
      conn,
      unit: svc,
      unitFile: unit,
      existsOnSource: async (p) => (validPath(p) ? shOk(conn, `${onSource(`test -e ${p}`)} >/dev/null 2>&1`, SETUP_TIMEOUT_MS) : false),
      copyFromSource: async (p) => {
        // Safe by construction: we only get here for a path that does NOT
        // exist on the target, so a single-file rsync cannot overwrite any
        // of this server's own OS. (safeCopyTarget guards whole-tree copies
        // into /usr, /bin … — a different question from restoring one
        // missing interpreter a copied unit needs.)
        if (!validPath(p) || (await shOk(conn, `test -e ${p}`))) return false;
        const dir = parentDir(p);
        if (!validPath(dir)) return false;
        await sh(conn, `mkdir -p ${dir}`, SETUP_TIMEOUT_MS);
        await execRemote(conn, rsyncPull(p, dir), SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
        return shOk(conn, `test -x ${p}`);
      },
      say: (l) => report(90, "Re-enabling services…", l),
    });
    for (const fix of pf.repairs) push({ step: `Service ${svc}`, status: "running", detail: fix });
    if (!pf.ok) {
      // Do NOT enable a unit we already know cannot exec: enabling it just
      // starts a crash-loop that survives every reboot.
      blockers.push(...pf.blockers);
      for (const b of pf.blockers) {
        push({ step: `Service ${svc}`, status: "failed", detail: `${b.why}. To finish: ${b.fix}` });
      }
      await report(90, "Re-enabling services…", `  ${svc}: not started — ${pf.blockers[0].why}.`);
      continue;
    }

    await execRemote(conn, `systemctl daemon-reload 2>/dev/null || true`, SETUP_TIMEOUT_MS).catch(() => {});
    const en = await execRemote(conn, `systemctl enable --now ${svc} 2>/dev/null`, SETUP_TIMEOUT_MS).catch(() => ({ code: 1 }));
    const active = await execRemote(conn, `systemctl is-active ${svc} 2>/dev/null`, SETUP_TIMEOUT_MS).then((x) => x.stdout.trim() === "active").catch(() => false);
    enabledUnits.push(svc);
    if (en.code === 0 && active) push({ step: `Service ${svc}`, status: "running", detail: "unit copied, enabled and active" });
    else push({ step: `Service ${svc}`, status: "copied", detail: "unit copied but not confirmed active — check `systemctl status`" });
  }

  // HEALTH GATE. `enable --now` succeeding proves nothing: nexis-next.service
  // was "enabled and started" 78 times over.
  if (enabledUnits.length) {
    await report(91, "Re-enabling services…", `Checking that the ${enabledUnits.length} service(s) we started are actually staying up.`);
    const gate = await unitHealthGate({ conn, units: enabledUnits, say: (l) => report(91, "Re-enabling services…", l) });
    blockers.push(...gate.blockers);
    for (const b of gate.blockers) {
      // Overwrite the optimistic line the enable loop pushed: the unit is not
      // running, and the summary must say so with the real error text.
      push({ step: `Service ${b.domain} is not running`, status: "failed", detail: `${b.why}. To fix: ${b.fix}` });
    }
    if (gate.healthy.length) {
      push({
        step: `Verify ${gate.healthy.length} migrated service(s) stay up`,
        status: "running",
        detail: `${gate.healthy.join(", ")} — active, and their systemd restart counters did not move while we watched, so they are not crash-looping`,
      });
    }
  }
}

