const PATH_RE = /^\/[A-Za-z0-9._/-]{0,255}$/;
const validPath = (p) => typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//");

function unfoldUnitLines(text) {
  const out = []; let acc = "";
  for (const raw of String(text ?? "").split("\n")) {
    const line = raw.replace(/\r$/, "");
    if (/\\\s*$/.test(line)) { acc += line.replace(/\\\s*$/, " "); continue; }
    out.push((acc + line).trim()); acc = "";
  }
  if (acc.trim()) out.push(acc.trim());
  return out;
}
function parseUnitExecPaths(text) {
  const out = []; const seen = new Set();
  for (const line of unfoldUnitLines(text)) {
    const m = /^(ExecStart|ExecStartPre|ExecStartPost)\s*=\s*(.*)$/.exec(line);
    if (!m) continue;
    let rhs = m[2].trim();
    if (!rhs) continue;
    rhs = rhs.replace(/^[-@+!]+\s*/, "").trim();
    if (!rhs) continue;
    let exe; const q = rhs[0];
    if (q === '"' || q === "'") { const end = rhs.indexOf(q, 1); exe = end > 0 ? rhs.slice(1, end) : rhs.slice(1); }
    else { exe = rhs.split(/\s+/)[0] ?? ""; }
    exe = exe.trim();
    if (!exe.startsWith("/")) continue;
    if (!validPath(exe)) continue;
    const key = `${m[1]}|${exe}`;
    if (seen.has(key) || out.length >= 12) continue;
    seen.add(key); out.push({ directive: m[1], path: exe });
  }
